<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require_once dirname(__DIR__).'/app/Auth/SessionUser.php';require_once dirname(__DIR__).'/app/Mail/InternalMail.php';require_once dirname(__DIR__).'/app/Mail/MessageBody.php';require_once dirname(__DIR__).'/app/UI/Conversation.php';
use TNL\Mail\InternalMail;
header('Cache-Control: no-store');header("Content-Security-Policy: default-src 'self'; style-src 'self'; frame-src 'self'; img-src 'self' data: https:; form-action 'self'; base-uri 'none'; frame-ancestors 'self'");$db=tnl_db();$who=\TNL\Auth\SessionUser::require($db);if($who['role']!=='employee'){http_response_code(403);exit('Chat disponible para usuarios del equipo.');}$user=(int)$who['id'];$error='';$selected=(int)($_GET['id']??0);$draft=(string)($_POST['body']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){tnl_check_csrf();try{$nonce=(string)($_POST['nonce']??'');if(!isset($_SESSION['chat_nonces'][$nonce]))throw new InvalidArgumentException('Formulario usado o caducado.');unset($_SESSION['chat_nonces'][$nonce]);$previous=$selected?InternalMail::read($db,$user,$selected):null;if($selected&&!$previous)throw new InvalidArgumentException('Conversación no disponible.');if($previous){$peerId=(int)$previous['sender_id']===$user?(int)$previous['recipient_id']:(int)$previous['sender_id'];$q=$db->prepare('SELECT internal_address FROM users WHERE id=? AND active=1');$q->execute([$peerId]);$recipient=(string)$q->fetchColumn();$subject=$previous['subject'];}else{$recipient=(string)($_POST['recipient']??'');$subject='Chat del equipo';}InternalMail::send($db,$user,$recipient,$subject,$draft,$previous?(int)$previous['id']:null,'plain');$created=(int)$db->lastInsertId();header('Location: chat.php?id='.$created);exit;}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'No se pudo enviar el mensaje.';}}
$message=$selected?InternalMail::read($db,$user,$selected):null;if($selected&&!$message){http_response_code(404);exit('Conversación no disponible.');}$thread=[];if($message)foreach(InternalMail::conversation($db,$user,$selected) as $part)$thread[]=['sort_id'=>(int)$part['id'],'headers'=>['from'=>$part['sender_name'],'date'=>$part['created_at'],'message-id'=>'<internal-'.$part['id'].'@tnl.invalid>'],'outgoing'=>(int)$part['sender_id']===$user,'body'=>\TNL\Mail\MessageBody::plain($part['body'],$part['format']),'html'=>\TNL\Mail\MessageBody::html($part['body'],$part['format'])];$threads=InternalMail::threads($db,$user);$total=count($threads);$pages=max(1,(int)ceil($total/10));$page=max(1,min($pages,(int)($_GET['page']??1)));$threads=array_slice($threads,($page-1)*10,10);$nonce=bin2hex(random_bytes(24));$_SESSION['chat_nonces']??=[];while(count($_SESSION['chat_nonces'])>20)array_shift($_SESSION['chat_nonces']);if(($_SERVER['HTTP_X_TNL_BACKGROUND']??'')!=='1')$_SESSION['chat_nonces'][$nonce]=time();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chat del equipo</title><link rel="stylesheet" href="assets/app.css?v=0.12.5"><script src="assets/workspace.js?v=0.12.5" defer></script><script src="assets/chat.js?v=0.12.5" defer></script></head><body class="team-chat-document" data-chat-document><main><header class="team-chat-heading"><a href="chat.php">Conversaciones</a><a href="chat.php?new=1">Nuevo chat</a></header><?php if($error):?><p class="error" role="alert"><?=tnl_escape($error)?></p><?php endif;?><?php if($message||isset($_GET['new'])):?><form method="post" class="team-chat-compose"><input type="hidden" name="csrf" value="<?=tnl_escape(tnl_csrf())?>"><input type="hidden" name="nonce" value="<?=tnl_escape($nonce)?>"><?php if(!$message):?><label>Para<input name="recipient" required data-directory autocomplete="off" placeholder="Usuario, nombre o cargo" value="<?=tnl_escape((string)($_POST['recipient']??''))?>"></label><?php endif;?><label class="sr-only" for="chat-body">Mensaje</label><textarea id="chat-body" name="body" rows="2" maxlength="50000" required placeholder="Escribe un mensaje…"><?=tnl_escape($draft)?></textarea><button>Enviar</button></form><?php endif;?><div data-live-region="team-chat"><?php if($message):?><?php \TNL\UI\Conversation::render($thread,true);?><?php elseif(!isset($_GET['new'])):?><?php foreach($threads as $m):?><a class="team-chat-row" href="chat.php?id=<?=(int)$m['id']?>"><strong><?=tnl_escape($m['peer_name'])?></strong><small><?=tnl_escape($m['created_at'])?></small><span><?=tnl_escape(substr(\TNL\Mail\MessageBody::plain($m['body'],$m['format']),0,100))?><?php if($m['unread_count']):?><b class="nav-count"><?=(int)$m['unread_count']?></b><?php endif;?></span></a><?php endforeach;?><?php if(!$threads):?><p class="empty-state">Inicia un chat con alguien de tu equipo.</p><?php endif;?><?php if($pages>1):?><nav class="pagination"><span>Página <?=$page?> de <?=$pages?></span><?php if($page>1):?><a href="?page=<?=$page-1?>">Más recientes</a><?php endif;?><?php if($page<$pages):?><a href="?page=<?=$page+1?>">Más antiguos</a><?php endif;?></nav><?php endif;?><?php endif;?></div></main></body></html>
